#requires -RunAsAdministrator
#requires -Version 5.1
[CmdletBinding()]param([switch]$RunGpUpdate)
$root='C:\ProgramData\BlueRidge\GPOReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "gpo-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'gpo-troubleshooting-bundle.log') -Append|Out-Null
try{$computer=Get-CimInstance Win32_ComputerSystem;$computer|Select Name,Domain,PartOfDomain,DomainRole|Export-Csv (Join-Path $d domain-state.csv) -NoTypeInformation;gpresult /r /scope computer|Out-File (Join-Path $d gpresult-computer.txt);gpresult /r /scope user|Out-File (Join-Path $d gpresult-user.txt);gpresult /h (Join-Path $d gpresult.html) /f|Out-Null;if($computer.PartOfDomain){nltest /dsgetdc:$($computer.Domain)|Out-File (Join-Path $d dc-discovery.txt);nltest /sc_verify:$($computer.Domain)|Out-File (Join-Path $d secure-channel.txt)}else{'Computer is not domain joined.'|Set-Content (Join-Path $d dc-discovery.txt);'Computer is not domain joined.'|Set-Content (Join-Path $d secure-channel.txt)};w32tm /query /status|Out-File (Join-Path $d time-status.txt);ipconfig /all|Out-File (Join-Path $d ipconfig-all.txt);Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-GroupPolicy/Operational';StartTime=(Get-Date).AddDays(-7)} -ErrorAction SilentlyContinue|Select -First 500 TimeCreated,Id,LevelDisplayName,Message|Export-Csv (Join-Path $d group-policy-events.csv) -NoTypeInformation;if($RunGpUpdate){gpupdate /force|Out-File (Join-Path $d gpupdate.txt)};Write-Host "GPO troubleshooting bundle: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
